// Single source of settings and prompts for this workflow. Other Code nodes
// read $('Config').first().json; the build injects config/config.local.json
// and prompts/*.md here and nowhere else.
// @inject config as CONFIG
// @end-inject
// @inject prompts/decide.md as PROMPT_DECIDE
// @end-inject
// @inject prompts/enrich.md as PROMPT_ENRICH
// @end-inject
return [{ json: { ...CONFIG, prompts: { decide: PROMPT_DECIDE, enrich: PROMPT_ENRICH } } }];

const CONFIG = $('Config').first().json;
// @inject src/parse-forward.js as tg
// @end-inject
// Owner-only intake (hard rule 2) and the privacy list before any model call
// (hard rule 7). Reads the trigger directly: Config sits between the trigger and
// this node. Anything not from the owner's private chat is dropped silently.
const out = [];
for (const u of $('Telegram Trigger').all()) {
  const m = u.json.message;
  if (!m || !tg.isOwner(m, CONFIG.telegram.owner_chat_id)) continue;
  const p = tg.parseTelegramMessage(m);
  if (!p.text) continue;
  const base = { message_id: m.message_id, chat_id: String(m.chat.id), source_id: p.source_id, source: 'Telegram', channel: 'telegram' };
  if (m.forward_origin && tg.isExcludedOrigin(m.forward_origin, CONFIG.filters.exclude_chats)) {
    out.push({ json: { ...base, excluded: true }, pairedItem: { item: 0 } });
    continue;
  }
  const firstLine = p.text.split('\n')[0].trim();
  out.push({
    json: {
      ...base,
      excluded: false,
      kind_hint: p.kind,
      from: p.sender || CONFIG.owner.name,
      subject: firstLine.length > 80 ? firstLine.slice(0, 79) + '…' : firstLine,
      received: p.original_date || new Date(m.date * 1000).toISOString(),
      body: p.text,
      link: p.link,
    },
    pairedItem: { item: 0 },
  });
}
return out;

const CONFIG = $('Config').first().json;
// @inject src/claude.js as claude
// @end-inject
const PROMPT = CONFIG.prompts.decide;
const e = $input.item.json;
const vars = {
  owner_name: CONFIG.owner.name,
  owner_context: CONFIG.owner.context,
  channel: e.channel,
  channel_guidance: PROMPT.guidance[e.channel] || '',
  sender: e.from,
  subject: e.subject,
  received: e.received,
  body: e.body,
};
return { json: { ...e, request: claude.buildClaudeRequest(PROMPT, vars, CONFIG.models) } };

const CONFIG = $('Config').first().json;
// @inject src/claude.js as claude
// @end-inject
// @inject src/decide-merge.js as decide
// @end-inject
// The owner forwarded this on purpose, so action is always needed; Haiku supplies
// the type, priority and estimate. DECIDER_MODE is forced to "haiku" until the Jev
// branch exists in this workflow.
const msg = $('Build decide request').item.json;
const response = $input.item.json;
const haiku = decide.parseHaikuDecision(claude.parseClaudeResponse(response));
const decision = decide.mergeDecision({ mode: 'haiku', threshold: CONFIG.decider.confidence_threshold, haiku, channel: 'telegram', forceActionNeeded: true });
const { request, ...rest } = msg;
return { json: { ...rest, ...decision, usage_decide: claude.usageOf(response) } };

const CONFIG = $('Config').first().json;
// @inject src/claude.js as claude
// @end-inject
const PROMPT = CONFIG.prompts.enrich;
const LANG = { ru: 'Russian', en: 'English', cs: 'Czech' };
const e = $input.item.json;
const vars = {
  owner_name: CONFIG.owner.name,
  owner_context: CONFIG.owner.context,
  title_language: LANG[CONFIG.language.titles] || CONFIG.language.titles,
  today: $now.setZone(CONFIG.timezone).toISODate(),
  channel: e.channel,
  action_type: e.action_type,
  priority: e.priority,
  sender: e.from,
  subject: e.subject,
  note: '',
  body: e.body,
};
return { json: { ...e, request: claude.buildClaudeRequest(PROMPT, vars, CONFIG.models) } };

// @inject src/claude.js as claude
// @end-inject
const e = $('Build enrich request').item.json;
const response = $input.item.json;
const r = claude.parseClaudeResponse(response);
const { request, ...rest } = e;
return {
  json: {
    ...rest,
    kind: e.action_type === 'email_reply' ? 'Reply' : 'Action',
    title: r.title,
    summary: r.summary,
    due: r.due,
    priority_reason: r.priority_reason,
    sender: e.from,
    shadow_decision: e.shadow || null,
    usage_enrich: claude.usageOf(response),
  },
};

const CONFIG = $('Config').first().json;
// @inject src/normalize-item.js as normalize
// @end-inject
// Everything after this node reads $('Normalize item').item.json, so the Notion
// nodes stay identical to WF1's.
const e = $input.item.json;
const item = normalize.normalizeItem(e, CONFIG.defaults);
return {
  json: {
    item,
    source_id: item.source_id,
    message_id: e.message_id,
    notion_properties: normalize.toNotionProperties(item),
    notion_update_properties: normalize.toNotionUpdateProperties(item),
  },
};

// Short confirmation with the Notion link. Input is the page from Create item
// or Update item; the item itself comes from Normalize item (SDK rule 7).
const CONFIG = $('Config').first().json;
const page = $input.item.json;
const { item } = $('Normalize item').item.json;
const created = ($('Exists?').item.json.results || []).length === 0;
const ru = CONFIG.language.digest === 'ru';
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const head = created ? (ru ? '✅ Задача создана' : '✅ Task created') : (ru ? '🔁 Уже была в Notion, обновлена' : '🔁 Already in Notion, updated');
const meta = [item.priority, item.estimate_min ? item.estimate_min + (ru ? ' мин' : ' min') : null, item.due ? (ru ? 'до ' : 'due ') + item.due : null].filter(Boolean).join(' · ');
const text = [head, '<b>' + esc(item.title) + '</b>', meta, page.url].filter(Boolean).join('\n');
return { json: { text } };
